// components/public/storefront-buying-help.tsx — Minimalist Full-Screen Buyer Guidance Section
// Palette & Typography: Obsidian Velvet & Soft Alabaster (Matching StorefrontTrustBar)
// 1. Transparent ambient canvas — zero heavy opaque color blocks
// 2. NO BOXES, NO SHADOWS, PURE TYPOGRAPHIC HAIRLINES (Linear/Raycast luxury style)
// 3. Crisp bone white / charcoal text hierarchy matching StorefrontTrustBar (#121316 / #EDEDF0 / #646A78 / #8F96A3)
// 4. Balanced 6-item layout (3 left / 3 right) for perfect geometric symmetry
// 5. Full-screen height (min-h-[100dvh] flex flex-col justify-center)

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import { sfx } from "@/src/lib/sound-effects";

interface FAQItem {
  id: string;
  question: string;
  answer: React.ReactNode;
}

const BUYING_FAQS: FAQItem[] = [
  {
    id: "purchases-location",
    question: "Where do I find my purchases?",
    answer: (
      <>
        Upon payment confirmation, your digital accounts and activation instructions unlock
        immediately on-screen and are permanently stored in your encrypted customer vault under{" "}
        <Link
          href="/?purchases=open"
          className="font-medium text-[#121316] dark:text-[#EDEDF0] underline underline-offset-4 hover:opacity-80 transition-opacity"
        >
          My purchases
        </Link>
        . You can access your orders at any time from the top navigation bar using your checkout
        email.
      </>
    ),
  },
  {
    id: "payment-window",
    question: "How long do I have to pay?",
    answer: (
      <>
        Orders are fulfilled on a first-to-pay basis. Once your transfer is confirmed by our
        automated listener (usually 2–5 seconds), your credentials are instantly unlocked. We accept direct QR payments via MariBank QR, GCash, and Maya. You can
        monitor live fulfillment status on the{" "}
        <Link
          href="/track"
          className="font-medium text-[#121316] dark:text-[#EDEDF0] underline underline-offset-4 hover:opacity-80 transition-opacity"
        >
          Track order
        </Link>{" "}
        page using your order reference code.
      </>
    ),
  },
  {
    id: "plan-durations",
    question: "Can I choose a different plan?",
    answer: (
      <>
        Yes. Available duration options (such as 1 Month or family tiers) are clearly displayed on
        each vending machine. You can compare real-time prices, available stock, and plan durations
        directly on the showroom floor before opening checkout.
      </>
    ),
  },
  {
    id: "replacement-guarantee",
    question: "What if my purchase has a problem?",
    answer: (
      <>
        Every verified purchase includes our standard 24-hour buyer protection window. If an
        account encounters unexpected credential issues or stops functioning within 24 hours of
        delivery, you can request an automated replacement directly inside{" "}
        <Link
          href="/?purchases=open"
          className="font-medium text-[#121316] dark:text-[#EDEDF0] underline underline-offset-4 hover:opacity-80 transition-opacity"
        >
          My purchases
        </Link>
        .
      </>
    ),
  },
  {
    id: "account-privacy",
    question: "Are delivered accounts private or shared?",
    answer: (
      <>
        100% verified and private. Every allocation is dedicated exclusively to a single buyer with
        zero profile sharing, zero screen collisions, and zero unauthorized interruptions.
      </>
    ),
  },
  {
    id: "support-and-terms",
    question: "Where can I get help?",
    answer: (
      <>
        Our complete operational rules, replacement guarantees, and privacy guidelines are detailed
        on the{" "}
        <Link
          href="/terms"
          className="font-medium text-[#121316] dark:text-[#EDEDF0] underline underline-offset-4 hover:opacity-80 transition-opacity"
        >
          Terms of Service
        </Link>{" "}
        page. For live assistance, click Help in the top navigation bar to connect directly with our
        support team.
      </>
    ),
  },
];

export function StorefrontBuyingHelp() {
  const [openIndex, setOpenIndex] = useState<number | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const toggleFAQ = (index: number) => {
    sfx.playKeypadClick();
    setOpenIndex((prev) => (prev === index ? null : index));
  };

  const leftColumnFAQs = BUYING_FAQS.slice(0, 3);
  const rightColumnFAQs = BUYING_FAQS.slice(3, 6);

  return (
    <section
      id="buying-help"
      aria-label="Buyer guidance and frequently asked questions"
      className="w-full min-h-[100dvh] flex flex-col justify-center relative z-20 py-16 sm:py-24 border-y border-neutral-200/80 dark:border-white/10 bg-transparent transition-colors"
    >
      {/* Anchor bridge for backwards compatibility with #protection links */}
      <span id="protection" className="scroll-mt-24 pointer-events-none absolute -top-12 left-0" />

      <div className="max-w-7xl mx-auto px-6 sm:px-10 lg:px-14 w-full">
        {/* ── SECTION HEADER: Calm, Elegant & Direct (Matching StorefrontTrustBar) ── */}
        <div className="mb-12 sm:mb-16 pb-8 border-b border-neutral-200/80 dark:border-white/10 text-left max-w-2xl">
          <span className="text-[11px] font-mono tracking-[0.25em] text-neutral-600 dark:text-neutral-400 uppercase select-none block mb-3 font-semibold">
            BUYER GUIDANCE SYSTEM
          </span>
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-bold tracking-tight text-neutral-950 dark:text-neutral-50 font-sans">
            Before you buy.
          </h2>
          <p className="text-sm sm:text-base text-neutral-800 dark:text-neutral-300 mt-3 font-sans leading-relaxed">
            Clear answers to common questions about selecting plans, QR payments, verified private access, and buyer protection.
          </p>
        </div>

        {/* ── 2 SYMMETRICAL TYPOGRAPHIC COLUMNS (3 LEFT / 3 RIGHT, PURE HAIRLINES) ── */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-x-14 sm:gap-x-20 gap-y-0 items-start">
          {/* Left Column: FAQs 01, 02, 03 */}
          <div className="flex flex-col">
            {leftColumnFAQs.map((faq, idx) => {
              const globalIdx = idx;
              const isOpen = openIndex === globalIdx;
              const buttonId = `faq-btn-${faq.id}`;
              const panelId = `faq-panel-${faq.id}`;

              return (
                <div
                  key={faq.id}
                  className="border-b border-neutral-200/80 dark:border-white/10 transition-colors"
                >
                  <button
                    type="button"
                    id={buttonId}
                    aria-expanded={isOpen}
                    aria-controls={panelId}
                    onClick={() => toggleFAQ(globalIdx)}
                    className="w-full flex items-center justify-between py-5 sm:py-6 text-left group cursor-pointer focus:outline-none focus-visible:ring-1 focus-visible:ring-neutral-400 dark:focus-visible:ring-white/20"
                  >
                    <div className="flex items-center gap-4 sm:gap-5 pr-4">
                      {/* Step Number in Soft Monospace */}
                      <span className="font-mono text-2xl sm:text-3xl font-light text-neutral-600 dark:text-neutral-400 tracking-tight shrink-0 select-none">
                        0{globalIdx + 1}
                      </span>
                      {/* Clean Question Title */}
                      <span className="text-base sm:text-lg font-bold text-neutral-950 dark:text-neutral-50 group-hover:text-black dark:group-hover:text-white transition-colors">
                        {faq.question}
                      </span>
                    </div>

                    {/* Pure Rotating Chevron (No Circle Box) */}
                    <span className="shrink-0 text-neutral-500 dark:text-neutral-400 group-hover:text-neutral-950 dark:group-hover:text-white transition-colors pl-2">
                      <ChevronDown
                        strokeWidth={1.5}
                        className={`w-4 h-4 transition-transform duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] ${
                          isOpen ? "rotate-180 text-neutral-950 dark:text-white" : ""
                        }`}
                      />
                    </span>
                  </button>

                  <AnimatePresence initial={false}>
                    {isOpen && (
                      <motion.div
                        id={panelId}
                        role="region"
                        aria-labelledby={buttonId}
                        initial={shouldReduceMotion ? false : { opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.28, ease: [0.16, 1, 0.3, 1] }}
                        className="overflow-hidden"
                      >
                        <div className="pl-10 sm:pl-12 pr-4 pb-6 pt-0">
                          <p className="text-sm sm:text-base leading-relaxed text-neutral-800 dark:text-neutral-300 max-w-[65ch]">
                            {faq.answer}
                          </p>
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              );
            })}
          </div>

          {/* Right Column: FAQs 04, 05, 06 */}
          <div className="flex flex-col">
            {rightColumnFAQs.map((faq, idx) => {
              const globalIdx = idx + 3;
              const isOpen = openIndex === globalIdx;
              const buttonId = `faq-btn-${faq.id}`;
              const panelId = `faq-panel-${faq.id}`;

              return (
                <div
                  key={faq.id}
                  className="border-b border-neutral-200/80 dark:border-white/10 transition-colors"
                >
                  <button
                    type="button"
                    id={buttonId}
                    aria-expanded={isOpen}
                    aria-controls={panelId}
                    onClick={() => toggleFAQ(globalIdx)}
                    className="w-full flex items-center justify-between py-5 sm:py-6 text-left group cursor-pointer focus:outline-none focus-visible:ring-1 focus-visible:ring-neutral-400 dark:focus-visible:ring-white/20"
                  >
                    <div className="flex items-center gap-4 sm:gap-5 pr-4">
                      {/* Step Number in Soft Monospace */}
                      <span className="font-mono text-2xl sm:text-3xl font-light text-neutral-600 dark:text-neutral-400 tracking-tight shrink-0 select-none">
                        0{globalIdx + 1}
                      </span>
                      {/* Clean Question Title */}
                      <span className="text-base sm:text-lg font-bold text-neutral-950 dark:text-neutral-50 group-hover:text-black dark:group-hover:text-white transition-colors">
                        {faq.question}
                      </span>
                    </div>

                    {/* Pure Rotating Chevron (No Circle Box) */}
                    <span className="shrink-0 text-neutral-500 dark:text-neutral-400 group-hover:text-neutral-950 dark:group-hover:text-white transition-colors pl-2">
                      <ChevronDown
                        strokeWidth={1.5}
                        className={`w-4 h-4 transition-transform duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] ${
                          isOpen ? "rotate-180 text-neutral-950 dark:text-white" : ""
                        }`}
                      />
                    </span>
                  </button>

                  <AnimatePresence initial={false}>
                    {isOpen && (
                      <motion.div
                        id={panelId}
                        role="region"
                        aria-labelledby={buttonId}
                        initial={shouldReduceMotion ? false : { opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.28, ease: [0.16, 1, 0.3, 1] }}
                        className="overflow-hidden"
                      >
                        <div className="pl-10 sm:pl-12 pr-4 pb-6 pt-0">
                          <p className="text-sm sm:text-base leading-relaxed text-neutral-800 dark:text-neutral-300 max-w-[65ch]">
                            {faq.answer}
                          </p>
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}

export default StorefrontBuyingHelp;
